-- ============================================================================
-- DEMI APPLICATION AND CLAIMS MANAGEMENT SYSTEM (DACMS)
-- PostgreSQL DDL Script
-- (including dummy data)
-- ============================================================================

CREATE TABLE "SYSTEM_ROLE" (
  "RoleID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RoleName" varchar(20) UNIQUE NOT NULL
);

CREATE TABLE "NWU_MODULE" (
  "ModuleID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ModuleCode" varchar(10) UNIQUE,
  "ModuleName" varchar(100) NOT NULL,
  "Description" text,
  "MinAcademicRequirement" decimal(4,2) NOT NULL DEFAULT 50.00
);

CREATE TABLE "PAYMENT_SCALE" (
  "ScaleID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RoleLevel" varchar(50) NOT NULL,
  "StandardHourlyRate" decimal(8,2) NOT NULL,
  "EffectiveYear" int NOT NULL
);

CREATE TABLE "APP_USER" (
  "UserID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "FName" varchar(100) NOT NULL,
  "LName" varchar(100) NOT NULL,
  "Email" varchar(100) UNIQUE NOT NULL,
  "PasswordHash" varchar(255) NOT NULL,
  "RoleID" int NOT NULL,
  "CreatedAt" timestamptz DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "STUDENT" (
  "StudentID" int PRIMARY KEY,
  "StudentNumber" varchar(15) UNIQUE NOT NULL,
  "StudyLevel" varchar(20) NOT NULL,
  "ContactDetails" varchar(50) NOT NULL,
  "BankName" varchar(50),
  "AccountNumber" varchar(30) NOT NULL,
  "BranchCode" varchar(10) NOT NULL
);

CREATE TABLE "SUPPORTING_DOCUMENT" (
  "DocumentID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StudentID" int NOT NULL,
  "DocumentType" varchar(50) NOT NULL,
  "FilePath" varchar(255) NOT NULL,
  "UploadTimestamp" timestamptz DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "LECTURER" (
  "LecturerID" int PRIMARY KEY,
  "Department" varchar(100) NOT NULL
);

CREATE TABLE "LECTURER_MODULE" (
  "LecturerID" int NOT NULL,
  "ModuleID" int NOT NULL,
  PRIMARY KEY ("LecturerID", "ModuleID")
);

CREATE TABLE "ADMINISTRATOR" (
  "AdminID" int PRIMARY KEY,
  "MFA_Enabled" boolean DEFAULT true,
  "BudgetAllocationRights" boolean DEFAULT true
);

CREATE TABLE "SECURITY_TOKEN" (
  "TokenID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserID" int NOT NULL,
  "JWT_Token" text NOT NULL,
  "IssuedAt" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "ExpiresAt" timestamptz NOT NULL
);

CREATE TABLE "MODULE_BUDGET" (
  "BudgetID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ModuleID" int NOT NULL,
  "LecturerID" int NOT NULL,
  "AllocatedBudget" decimal(10,2) NOT NULL,
  "CurrentBudgetUsage" decimal(10,2) DEFAULT 0.00,
  "MaxAllowableWorkHours" int NOT NULL,
  "AcademicYear" int NOT NULL
);

CREATE TABLE "STUDENT_MODULE_GRADE" (
  "GradeID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StudentID" int NOT NULL,
  "ModuleID" int NOT NULL,
  "GradeAchieved" decimal(5,2) NOT NULL
);

CREATE TABLE "DEMI_LISTING" (
  "ListingID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ModuleID" int NOT NULL,
  "LecturerID" int NOT NULL,
  "Deadline" timestamptz NOT NULL,
  "MinimumGrade" decimal(5,2) NOT NULL
);

CREATE TABLE "DEMI_APPLICATION" (
  "ApplicationID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StudentID" int NOT NULL,
  "ListingID" int NOT NULL,
  "ApplicationStatus" varchar(20) DEFAULT 'Pending',
  "VerificationEligibilityStatus" varchar(20) DEFAULT 'Unverified',
  "DateSubmitted" timestamptz DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "DEMI_POSITION" (
  "PositionID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ApplicationID" int UNIQUE NOT NULL,
  "PaymentScaleID" int NOT NULL,
  "StartDate" timestamptz NOT NULL,
  "TerminationDate" timestamptz
);

CREATE TABLE "WORK_SESSION" (
  "SessionID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "PositionID" int NOT NULL,
  "StartTime" timestamptz NOT NULL,
  "EndTime" timestamptz,
  "TotalHoursWorked" decimal(5,2),
  "EstimatedRemuneration" decimal(8,2),
  "LecturerApproval" boolean DEFAULT false
);

CREATE TABLE "REMUNERATION_CLAIM" (
  "ClaimID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ClaimReferenceNumber" varchar(50) UNIQUE NOT NULL,
  "ApplicationID" int NOT NULL,
  "ModuleID" int NOT NULL,
  "TotalHoursClaimed" decimal(5,2) NOT NULL,
  "TotalClaimAmount" decimal(10,2) NOT NULL,
  "HourlyRateApplied" decimal(10,2) NOT NULL,
  "ClaimStatus" varchar(20) DEFAULT 'Pending',
  "SubmissionDate" timestamptz DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "NOTIFICATION" (
  "NotificationID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RecipientUserID" int NOT NULL,
  "NotificationType" varchar(50) NOT NULL,
  "Message" text NOT NULL,
  "IsRead" boolean DEFAULT false,
  "CreatedTimestamp" timestamptz DEFAULT CURRENT_TIMESTAMP
);

-- Column Comments
COMMENT ON COLUMN "SYSTEM_ROLE"."RoleName" IS 'Student, Lecturer, Administrator';
COMMENT ON COLUMN "NWU_MODULE"."ModuleCode" IS 'e.g., CMPG323';
COMMENT ON COLUMN "NWU_MODULE"."MinAcademicRequirement" IS 'Automated academic check threshold';
COMMENT ON COLUMN "PAYMENT_SCALE"."RoleLevel" IS 'e.g., Undergraduate Demi, Postgraduate Demi';
COMMENT ON COLUMN "APP_USER"."Email" IS 'University credentials for login';
COMMENT ON COLUMN "APP_USER"."PasswordHash" IS 'Password hashed with Bcrypt';
COMMENT ON COLUMN "SUPPORTING_DOCUMENT"."DocumentType" IS 'Academic Transcript, Certified ID, Bank Letter, etc.';
COMMENT ON COLUMN "SECURITY_TOKEN"."JWT_Token" IS 'Session authentication token';
COMMENT ON COLUMN "DEMI_APPLICATION"."ApplicationStatus" IS 'Pending, In Review, Approved, Rejected';
COMMENT ON COLUMN "DEMI_APPLICATION"."VerificationEligibilityStatus" IS 'Automated result check';
COMMENT ON COLUMN "WORK_SESSION"."TotalHoursWorked" IS 'Duration calculated upon clock-out';
COMMENT ON COLUMN "WORK_SESSION"."LecturerApproval" IS 'Session verification';
COMMENT ON COLUMN "REMUNERATION_CLAIM"."ClaimStatus" IS 'Pending, Under Review, Verified';
COMMENT ON COLUMN "NOTIFICATION"."NotificationType" IS 'Application Update, Claim Submission, etc.';

-- Foreign Keys
ALTER TABLE "APP_USER" ADD FOREIGN KEY ("RoleID") REFERENCES "SYSTEM_ROLE" ("RoleID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "STUDENT" ADD FOREIGN KEY ("StudentID") REFERENCES "APP_USER" ("UserID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "SUPPORTING_DOCUMENT" ADD FOREIGN KEY ("StudentID") REFERENCES "STUDENT" ("StudentID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "LECTURER" ADD FOREIGN KEY ("LecturerID") REFERENCES "APP_USER" ("UserID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "LECTURER_MODULE" ADD FOREIGN KEY ("LecturerID") REFERENCES "LECTURER" ("LecturerID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "LECTURER_MODULE" ADD FOREIGN KEY ("ModuleID") REFERENCES "NWU_MODULE" ("ModuleID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "ADMINISTRATOR" ADD FOREIGN KEY ("AdminID") REFERENCES "APP_USER" ("UserID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "SECURITY_TOKEN" ADD FOREIGN KEY ("UserID") REFERENCES "APP_USER" ("UserID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "MODULE_BUDGET" ADD FOREIGN KEY ("ModuleID") REFERENCES "NWU_MODULE" ("ModuleID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "MODULE_BUDGET" ADD FOREIGN KEY ("LecturerID") REFERENCES "LECTURER" ("LecturerID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "STUDENT_MODULE_GRADE" ADD FOREIGN KEY ("StudentID") REFERENCES "STUDENT" ("StudentID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "STUDENT_MODULE_GRADE" ADD FOREIGN KEY ("ModuleID") REFERENCES "NWU_MODULE" ("ModuleID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "DEMI_LISTING" ADD FOREIGN KEY ("ModuleID") REFERENCES "NWU_MODULE" ("ModuleID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "DEMI_LISTING" ADD FOREIGN KEY ("LecturerID") REFERENCES "LECTURER" ("LecturerID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "DEMI_APPLICATION" ADD FOREIGN KEY ("StudentID") REFERENCES "STUDENT" ("StudentID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "DEMI_APPLICATION" ADD FOREIGN KEY ("ListingID") REFERENCES "DEMI_LISTING" ("ListingID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "DEMI_POSITION" ADD FOREIGN KEY ("ApplicationID") REFERENCES "DEMI_APPLICATION" ("ApplicationID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "DEMI_POSITION" ADD FOREIGN KEY ("PaymentScaleID") REFERENCES "PAYMENT_SCALE" ("ScaleID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "WORK_SESSION" ADD FOREIGN KEY ("PositionID") REFERENCES "DEMI_POSITION" ("PositionID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "REMUNERATION_CLAIM" ADD FOREIGN KEY ("ApplicationID") REFERENCES "DEMI_APPLICATION" ("ApplicationID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "REMUNERATION_CLAIM" ADD FOREIGN KEY ("ModuleID") REFERENCES "NWU_MODULE" ("ModuleID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "NOTIFICATION" ADD FOREIGN KEY ("RecipientUserID") REFERENCES "APP_USER" ("UserID") DEFERRABLE INITIALLY IMMEDIATE;

